package main

import (
	"encoding/json"
	"fmt"
	"net/http"
)

var ProoductList []Prooduct

type Prooduct struct {
	ID          int     `json:"id"`
	Title       string  `json:"title"`
	Discription string  `json:"discription"`
	Price       float64 `json:"price"`
	ImgUrl      string  `json:"imgUrl"`
}

func getproduct(w http.ResponseWriter, r *http.Request) {
	handleCros(w)
	handlePreflightReq(w, r)

	if r.Method != "GET" {
		http.Error(w, "Plz enter the valid product", 400)
		return
	}
	sendData(w, ProoductList, 200)

}

//id ,Title, Discription, Price, ImgUrl
//r.body=>id ,Title, Discription, Price, ImgUrl=>Product er ekta object =>ProductLis=>append
/*
   1.take body information(id ,Title, Discription, Price, ImgUrl) from r.body
   2.create an instance using Product struct with the body information
   3.append the object into product list

*/
func addproduct(w http.ResponseWriter, r *http.Request) {
	handleCros(w)
	handlePreflightReq(w, r)
	if r.Method != "POST" {
		http.Error(w, "Plz enter the valid POST", 400)
		return
	}

	var newProduct Prooduct
	decoder := json.NewDecoder(r.Body)
	err := decoder.Decode(&newProduct)
	if err != nil {
		fmt.Println(err)
		http.Error(w, "Plz enter the valid JSON", 400)
		return
	}
	newProduct.ID = len(ProoductList) + 1
	ProoductList = append(ProoductList, newProduct)

	sendData(w, newProduct, 201)

}

func handleCros(w http.ResponseWriter) {
	w.Header().Set("Access-Control-Allow-Origin", "*")
	w.Header().Set("Access-Control-Allow-Methods", "GET,POST,PUT,PATCH,DELETE,OPTION")
	w.Header().Set("Access-Control-Allow-Headers", "Content-Type")
	w.Header().Set("Content-Type", "application/json")

}

func handlePreflightReq(w http.ResponseWriter, r *http.Request) {
	if r.Method == "OPTIONS" { //prefight request

		w.WriteHeader(200)

	}
}

func sendData(w http.ResponseWriter, data interface{}, statusCode int) {
	w.WriteHeader(statusCode)
	encoder := json.NewEncoder(w)
	encoder.Encode(data)
}

func main() {
	mux := http.NewServeMux() //router

	mux.HandleFunc("/getproduct", getproduct) //route
	mux.HandleFunc("/addproduct", addproduct)

	fmt.Println("Server Runing on:8080")
	err := http.ListenAndServe(":8080", mux) //star a server in a specific port
	if err != nil {
		fmt.Println("Error Starting the Server:", err)
	}
}

